#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Returns a new heap copy of s. The caller frees it. */
char *str_copy(const char *s)
{
    size_t n = strlen(s);
    char *copy = malloc(n + 1);
    if (copy == NULL) return NULL;
    memcpy(copy, s, n + 1);
    return copy;
}

int main(void)
{
    char line[32] = "Wanjiru";
    char *saved = str_copy(line);
    strcpy(line, "Otieno");        /* the buffer gets reused */
    printf("buffer: %s, saved copy: %s\n", line, saved);
    printf("\"%s\" is %zu letters and needs %zu bytes\n", saved, strlen(saved), strlen(saved) + 1);
    free(saved);
    return 0;
}

