/* Returns a new heap string a + sep + b. The caller frees it. */
char *join(const char *a, const char *sep, const char *b)
{
    size_t la = strlen(a), ls = strlen(sep), lb = strlen(b);
    char *out = my_alloc(la + ls + lb + 1);
    if (out == NULL) return NULL;
    memcpy(out, a, la);
    memcpy(out + la, sep, ls);
    memcpy(out + la + ls, b, lb);
    out[la + ls + lb] = '\0';
    return out;
}

