#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Archie's counting helpers: use these instead of malloc/realloc/free so the tests can see leaks. */
int live_allocs = 0;          /* blocks handed out and not yet freed */
size_t last_alloc_size = 0;   /* size of the most recent allocation */

void *my_alloc(size_t size)
{
    void *p = malloc(size);
    if (p != NULL) {
        live_allocs++;
        last_alloc_size = size;
    }
    return p;
}

void *my_realloc(void *p, size_t size)
{
    void *q = realloc(p, size);
    if (q != NULL) {
        if (p == NULL) live_allocs++;   /* realloc(NULL, n) is a new block */
        last_alloc_size = size;
    }
    return q;
}

void my_free(void *p)
{
    if (p != NULL) {
        live_allocs--;
        free(p);
    }
}

void free_fields(char **fields, int count)
{
    if (fields == NULL) return;
    for (int i = 0; i < count; i++)
        my_free(fields[i]);       /* each field first... */
    my_free(fields);              /* ...then the array that held them */
}

/* Splits line at sep. Returns a heap array of heap strings; free it with free_fields. */
char **split(const char *line, char sep, int *count)
{
    int n = 1;
    for (const char *p = line; *p != '\0'; p++)
        if (*p == sep) n++;

    char **fields = my_alloc(n * sizeof *fields);
    if (fields == NULL) {
        *count = 0;
        return NULL;
    }

    const char *start = line;
    for (int i = 0; i < n; i++) {
        const char *end = start;
        while (*end != '\0' && *end != sep) end++;
        size_t len = (size_t)(end - start);
        fields[i] = my_alloc(len + 1);
        if (fields[i] == NULL) {          /* undo what we made so far */
            free_fields(fields, i);
            *count = 0;
            return NULL;
        }
        memcpy(fields[i], start, len);
        fields[i][len] = '\0';
        start = end + 1;                  /* skip the separator */
    }
    *count = n;
    return fields;
}
